-- Reusable Alumdoor BOM Rule authority.
--
-- Cutting Policy remains the parent-door geometry authority. BOM Rule only describes how a
-- component consumes that geometry. The master is reusable by many BOMs/templates and keeps
-- source provenance separate from the effective owner-confirmed formula.

INSERT OR REPLACE INTO doctype_definitions(
  tenant_id, doctype, module, is_custom, is_submittable, is_child, revision,
  metadata_json, disabled, modified_by, modified_at
)
SELECT DISTINCT
  tenant_id,
  'BOM Rule',
  'Manufacturing',
  0, 0, 0, 1,
  json('{"name":"BOM Rule","module":"Manufacturing","autoname":"field:rule_code","title_field":"rule_name","search_fields":"rule_code,rule_name,description,source_formula_text","is_submittable":false,"is_child":false,"track_changes":true,"revision":1,"fields":[{"fieldname":"rule_code","label":"Mã quy tắc","fieldtype":"Data","required":true,"unique":true,"in_list_view":true},{"fieldname":"rule_name","label":"Tên quy tắc","fieldtype":"Data","required":true,"in_list_view":true},{"fieldname":"description","label":"Mô tả","fieldtype":"Small Text"},{"fieldname":"result_kind","label":"Loại kết quả","fieldtype":"Select","options":"LENGTH\nAREA\nCOUNT\nWEIGHT\nCONSTANT","required":true,"in_list_view":true},{"fieldname":"result_uom","label":"ĐVT kết quả / tiêu hao","fieldtype":"Link","options":"UOM","required":true,"in_list_view":true},{"fieldname":"source_field","label":"Trường nguồn từ hàng cha","fieldtype":"Link","options":"Geometry Field"},{"fieldname":"operator","label":"Phép tính","fieldtype":"Select","options":"COPY\nADD\nSUBTRACT\nMULTIPLY\nDIVIDE\nCONSTANT","default":"COPY","required":true},{"fieldname":"operand","label":"Giá trị cộng / trừ / nhân / chia","fieldtype":"Float","default":0},{"fieldname":"multiply","label":"Hệ số nhân","fieldtype":"Float","default":1},{"fieldname":"divide","label":"Hệ số chia","fieldtype":"Float","default":1},{"fieldname":"qty_per_set","label":"Số lượng mỗi bộ","fieldtype":"Float","default":1,"required":true},{"fieldname":"rounding","label":"Làm tròn","fieldtype":"Select","options":"NONE\nROUND\nCEIL\nFLOOR","default":"NONE"},{"fieldname":"precision","label":"Số chữ số","fieldtype":"Int","default":6},{"fieldname":"formula_json","label":"Công thức canonical JSON","fieldtype":"Long Text","read_only":true},{"fieldname":"formula_display","label":"Công thức hiển thị","fieldtype":"Data","read_only":true,"in_list_view":true},{"fieldname":"version","label":"Phiên bản","fieldtype":"Int","default":1,"required":true,"in_list_view":true},{"fieldname":"disabled","label":"Ngưng dùng","fieldtype":"Check","default":0,"in_list_view":true},{"fieldname":"applicability","label":"Áp dụng cho","fieldtype":"Table","options":"BOM Rule Applicability"},{"fieldname":"authority_type","label":"Nguồn thẩm quyền","fieldtype":"Select","options":"SOURCE\nOWNER_CONFIRMED\nENGINEERING_INFERENCE","default":"SOURCE","required":true},{"fieldname":"source_sheet","label":"Sheet nguồn","fieldtype":"Data"},{"fieldname":"source_row","label":"Dòng nguồn","fieldtype":"Int"},{"fieldname":"source_formula_text","label":"Công thức nguồn gốc","fieldtype":"Small Text"},{"fieldname":"source_formula_code","label":"Mã công thức nguồn","fieldtype":"Data"},{"fieldname":"source_note","label":"Ghi chú nguồn / xác nhận","fieldtype":"Small Text"},{"fieldname":"confirmed_by","label":"Người xác nhận","fieldtype":"Data"},{"fieldname":"confirmed_at","label":"Thời điểm xác nhận","fieldtype":"Datetime"}],"permissions":[],"custom":false}'),
  0, 'migration-0134', '2026-08-19T05:50:00.000Z'
FROM doctype_definitions
WHERE doctype IN ('BOM Template', 'Bill of Materials');

