-- Existing template child keeps its source snapshot but can now link to the reusable master.
UPDATE doctype_definitions
SET revision = 2,
    metadata_json = json('{"name":"BOM Component Rule","module":"Manufacturing","is_submittable":false,"is_child":true,"track_changes":false,"revision":2,"fields":[{"fieldname":"rule_code","label":"Mã dòng quy tắc","fieldtype":"Data","required":true,"in_list_view":true},{"fieldname":"component_key","label":"Khóa thành phần","fieldtype":"Data"},{"fieldname":"item_code","label":"Vật tư","fieldtype":"Link","options":"Item","required":true,"in_list_view":true},{"fieldname":"bom_rule","label":"Quy tắc BOM dùng chung","fieldtype":"Link","options":"BOM Rule","in_list_view":true},{"fieldname":"bom_rule_version","label":"Phiên bản quy tắc","fieldtype":"Int","read_only":true},{"fieldname":"stock_uom","label":"Đơn vị tồn","fieldtype":"Link","options":"UOM"},{"fieldname":"conditions_json","label":"Điều kiện JSON","fieldtype":"Code"},{"fieldname":"priority","label":"Ưu tiên","fieldtype":"Int","default":0},{"fieldname":"sequence","label":"Thứ tự","fieldtype":"Int","default":0},{"fieldname":"quantity_formula_json","label":"Công thức cũ / fallback","fieldtype":"Code"},{"fieldname":"bom_rule_formula_snapshot","label":"Snapshot công thức BOM Rule","fieldtype":"Long Text","read_only":true},{"fieldname":"source_row","label":"Dòng nguồn","fieldtype":"Int"},{"fieldname":"source_uom","label":"ĐVT nguồn","fieldtype":"Data"},{"fieldname":"source_formula","label":"Công thức nguồn","fieldtype":"Small Text"},{"fieldname":"note","label":"Ghi chú","fieldtype":"Small Text"}],"permissions":[],"custom":false}'),
    modified_by = 'migration-0134',
    modified_at = '2026-08-19T05:50:00.000Z'
