 Index","fieldtype":"Int"},{"fieldname":"source_parent_row","label":"Source Parent Row","fieldtype":"Int"},{"fieldname":"source_item_code","label":"Raw Material Source Code","fieldtype":"Data"},{"fieldname":"source_item_name","label":"Raw Material Source Name","fieldtype":"Data"},{"fieldname":"source_uom","label":"Source UOM","fieldtype":"Data"},{"fieldname":"source_qty_or_formula","label":"Source Qty / Formula","fieldtype":"Data"},{"fieldname":"source_formula_code","label":"Source Formula Code","fieldtype":"Data"},{"fieldname":"source_formula_text","label":"Source Formula Text","fieldtype":"Long Text"},{"fieldname":"resolution_reason","label":"Resolution Reason","fieldtype":"Data"},{"fieldname":"rate","label":"Rate","fieldtype":"Currency","read_only":true},{"fieldname":"source_warehouse","label":"Source Warehouse","fieldtype":"Link","options":"Warehouse"}],"permissions":[],"custom":false}'),
